import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        boolean spike = false;
        for (int i = 0; i < n; i++) {
            int second = sc.nextInt(), pause = sc.nextInt();
            if (pause >= 50) {
                System.out.println("SPIKE " + second + " " + pause);
                spike = true;
            }
        }
        if (!spike) System.out.println("STABLE");
    }
}

