import java.util.*;

public class Main {
    static long percentile(long[] sorted, int percent) {
        int rank = (percent * sorted.length + 99) / 100;
        return sorted[rank - 1];
    }

    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] xs = new long[n];
        for (int i = 0; i < n; i++) xs[i] = sc.nextLong();
        Arrays.sort(xs);
        System.out.println("p50=" + percentile(xs, 50) + " p95=" + percentile(xs, 95));
    }
}

